files.src/pages/[lang]/restaurantes.astro:
---
import Layout from '@/layouts/Layout.astro';
import { getCollection } from 'astro:content';
import { supportedLanguages, getTranslations } from '@/lib/i18n';
import { generateBreadcrumbSchema } from '@/lib/seo';
import { Utensils, MapPin, Award, ShieldCheck } from 'lucide-react';

export async function getStaticPaths() {
  return supportedLanguages.map((lang) => ({
    params: { lang },
  }));
}

const { lang = 'es' } = Astro.params;
const currentLang = (lang === 'es' || lang === 'en' || lang === 'de') ? lang : 'es';

const pagesCollection = await getCollection('pages');
const restEntry = pagesCollection.find((p) => p.id === 'restaurants' || p.id.includes('restaurants'));
const content = restEntry ? restEntry.data : null;

const badge = content?.badge?.[currentLang] || 'Guía Culinaria & Templos';
const title = content?.title?.[currentLang] || 'Restaurantes & Templos de la Tortilla';
const subtitle = content?.subtitle?.[currentLang] || 'Los establecimientos más aclamados de España.';
const restaurants = content?.restaurants || [];

const pageTitle = `${title} | tortilladepatatas.org`;
const breadcrumbSchema = generateBreadcrumbSchema([
  { name: 'Inicio', url: `/${currentLang}` },
  { name: 'Enciclopedia', url: `/${currentLang}/enciclopedia` },
  { name: title, url: `/${currentLang}/restaurantes` },
]);
---

<Layout title={pageTitle} description={subtitle} lang={currentLang} schema={[breadcrumbSchema]}>
  <div class="container mx-auto px-4 py-10 md:py-16 max-w-5xl space-y-12">
    <header class="text-center max-w-3xl mx-auto space-y-4">
      <div class="inline-flex items-center gap-2 px-3.5 py-1 rounded-full bg-[#F5E6BE] text-[#8D6E63] border border-amber-300 text-xs font-bold shadow-2xs">
        <Utensils class="w-3.5 h-3.5" />
        <span>{badge}</span>
      </div>

      <h1 class="text-3xl sm:text-4xl font-serif-heading font-extrabold text-[#292521]">
        {title}
      </h1>

      <p class="text-base sm:text-lg text-foreground/80 leading-relaxed">
        {subtitle}
      </p>
    </header>

    <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
      {restaurants.map((rest: any) => (
        <div class="card-notebook p-6 rounded-2xl border border-[#E8E2D5] bg-[#FCF9F2] space-y-4 shadow-xs">
          <div class="flex items-start justify-between gap-2">
            <div>
              <h2 class="text-2xl font-serif-heading font-bold text-[#292521]">{rest.name}</h2>
              <p class="text-xs font-bold text-[#8D6E63] flex items-center gap-1 mt-1">
                <MapPin class="w-3.5 h-3.5" />
                <span>{rest.city}</span>
              </p>
            </div>
            {rest.award && (
              <span class="inline-flex items-center gap-1 text-[11px] font-bold bg-[#FFB800]/20 text-[#8D6E63] px-2.5 py-1 rounded-full border border-amber-300">
                <Award class="w-3.5 h-3.5" />
                <span>{rest.award}</span>
              </span>
            )}
          </div>

          <p class="text-sm text-foreground/80 leading-relaxed">
            {rest.description?.[currentLang] || rest.description}
          </p>

          <div class="pt-2 border-t border-[#E8E2D5] text-xs font-semibold text-muted-foreground">
            Estilo: <strong class="text-foreground">{rest.style}</strong>
          </div>
        </div>
      ))}
    </div>

    <section class="card-notebook p-5 rounded-2xl bg-[#FCF9F2] border-l-4 border-l-[#2E7D32] border border-[#E8E2D5]">
      <div class="flex items-start gap-3 text-xs sm:text-sm text-foreground/90">
        <ShieldCheck class="w-5 h-5 text-[#2E7D32] shrink-0 mt-0.5" />
        <p>
          Control Sanitario en Hostelería: La normativa vigente para restauración comercial exige el uso de huevo pasteurizado o garantizar **70°C for 2 minutes** de cocción bactericida, limitando el consumo a **4 hours** a temperatura ambiente.
        </p>
      </div>
    </section>
  </div>
</Layout>

