files.src/styles/_mixins.scss:
@use 'variables' as *;

// Notebook Card Elevation
@mixin notebook-card {
  background-color: $bg-card;
  border-radius: 12px;
  border: 1px solid $border-notebook;
  box-shadow: 0 4px 12px rgba(141, 110, 99, 0.08);
  position: relative;
  transition: all 0.25s ease-in-out;

  &:hover {
    box-shadow: 0 8px 20px rgba(141, 110, 99, 0.14);
    transform: translateY(-2px);
  }
}

// Stacked Parchment Depth
@mixin stacked-parchment {
  background-color: $bg-parchment;
  border: 1px solid $border-notebook;
  border-radius: 16px;
  box-shadow: 0 4px 6px -1px rgba(74, 59, 50, 0.06), 
              0 2px 4px -1px rgba(74, 59, 50, 0.04),
              0 0 0 1px rgba(232, 226, 213, 0.8),
              0 8px 16px -4px rgba(74, 59, 50, 0.08);
}

// Chef Note Annotation
@mixin chef-note {
  font-family: $font-script-handwritten;
  font-size: 1.25rem;
  line-height: 1.35;
  color: #3D2C1E;
  background-color: #FFF8E7;
  border-left: 4px solid $color-yolk-gold;
  padding: 0.875rem 1.25rem;
  border-radius: 0 10px 10px 0;
  box-shadow: 0 2px 8px rgba(255, 184, 0, 0.12);
}

// Safety Badge Status Mixin
@mixin safety-badge($status) {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.625rem;
  border-radius: 9999px;

  @if $status == 'danger' {
    color: $color-risk-danger;
    background-color: rgba(176, 0, 32, 0.1);
    border: 1px solid rgba(176, 0, 32, 0.25);
  } @else if $status == 'warning' {
    color: #8D6000;
    background-color: rgba(255, 193, 7, 0.18);
    border: 1px solid rgba(255, 193, 7, 0.35);
  } @else if $status == 'safe' {
    color: $color-risk-safe;
    background-color: rgba(46, 125, 50, 0.1);
    border: 1px solid rgba(46, 125, 50, 0.25);
  }
}

// Responsive Media Query Helpers
@mixin mobile-only {
  @media (max-width: #{$bp-tablet - 1px}) {
    @content;
  }
}

@mixin tablet-up {
  @media (min-width: #{$bp-tablet}) {
    @content;
  }
}

@mixin desktop-up {
  @media (min-width: #{$bp-desktop}) {
    @content;
  }
}

