files.src/layouts/BaseLayout.astro:
---
import '@/index.css';
import Header from '@/components/layout/Header.tsx';
import Footer from '@/components/layout/Footer.tsx';
import { getCanonicalUrl, getHreflangs } from '@/lib/seo';

interface Props {
  title?: string;
  description?: string;
  lang?: string;
  image?: string;
  type?: string;
  schema?: Record<string, any> | Array<Record<string, any>>;
  showHeader?: boolean;
  showFooter?: boolean;
}

const {
  title = "Tortilla de Patatas - Guía Culinaria & Calculadora Científica",
  description = "Portal internacional sobre la tortilla de patatas: recetas tradicionales (Betanzos, con cebolla), proporciones calculadas, historia y parámetros de seguridad alimentaria bactericida.",
  lang = "es",
  image = "/images/clasica.jpg",
  type = "website",
  schema,
  showHeader = true,
  showFooter = true,
} = Astro.props;

const canonicalUrl = getCanonicalUrl(Astro.url.pathname);
const hreflangs = getHreflangs(Astro.url.pathname);
const siteName = "tortilladepatatas.org";
const imageUrl = image.startsWith('http') ? image : `https://tortilladepatatas.org${image}`;
---

<!doctype html>
<html lang={lang} class="scroll-smooth">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <meta name="theme-color" content="#FFB800" />
    <link rel="icon" type="image/svg+xml" href="/favicon.svg" />
    <meta name="generator" content={Astro.generator} />

    <!-- Title & SEO Meta -->
    <title>{title}</title>
    <meta name="description" content={description} />
    <meta name="keywords" content="tortilla de patatas, Spanish omelette, tortilla española, receta tortilla patatas, Betanzos, tortilla con cebolla, seguridad alimentaria, 70°C for 2 minutes" />
    <meta name="author" content="tortilladepatatas.org" />

    <!-- Canonical URL -->
    <link rel="canonical" href={canonicalUrl} />

    <!-- Hreflang Multilingual Tags -->
    {hreflangs.map((item) => (
      <link rel="alternate" hreflang={item.lang} href={item.href} />
    ))}

    <!-- Open Graph Metadata -->
    <meta property="og:site_name" content={siteName} />
    <meta property="og:title" content={title} />
    <meta property="og:description" content={description} />
    <meta property="og:type" content={type} />
    <meta property="og:url" content={canonicalUrl} />
    <meta property="og:image" content={imageUrl} />
    <meta property="og:locale" content={lang === 'es' ? 'es_ES' : lang === 'de' ? 'de_DE' : 'en_US'} />

    <!-- Twitter Card Metadata -->
    <meta name="twitter:card" content="summary_large_image" />
    <meta name="twitter:title" content={title} />
    <meta name="twitter:description" content={description} />
    <meta name="twitter:image" content={imageUrl} />

    <!-- Design System Typography Google Fonts -->
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
      href="https://fonts.googleapis.com/css2?family=Caveat:wght@500;600;700&family=Playfair+Display:ital,wght@0,600;0,700;0,800;1,600&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap"
      rel="stylesheet"
    />

    <!-- Google Consent Mode Default & gtag.js -->
    <script is:inline>
      window.dataLayer = window.dataLayer || [];
      function gtag(){dataLayer.push(arguments);}

      // Default all tracking to 'denied'
      gtag('consent', 'default', {
        'analytics_storage': 'denied',
        'ad_storage': 'denied'
      });
    </script>

    <!-- Google tag (gtag.js) -->
    <script async src="https://www.googletagmanager.com/gtag/js?id=G-J9L1DQMKPR"></script>
    <script is:inline>
      gtag('js', new Date());
      gtag('config', 'G-J9L1DQMKPR');
    </script>

    <!-- Structured Data (JSON-LD) -->
    {schema && (
      <script
        type="application/ld+json"
        set:html={JSON.stringify(Array.isArray(schema) ? schema : [schema])}
      />
    )}

    <slot name="head" />
  </head>
  <body class="bg-background text-foreground font-sans antialiased min-h-screen flex flex-col">
    {showHeader && (
      <Header lang={lang} currentPath={Astro.url.pathname} client:load />
    )}

    <main id="main-content" class="flex-1 w-full">
      <slot />
    </main>

    {showFooter && (
      <Footer lang={lang} currentPath={Astro.url.pathname} client:load />
    )}

    <!-- Cookie Consent Banner -->
    <div
      id="cookie-banner"
      style="
        display: none;
        position: fixed;
        bottom: 16px;
        right: 16px;
        left: 16px;
        max-width: 420px;
        margin: 0 auto;
        background: #292521;
        color: #FFF7EA;
        padding: 12px 16px;
        border-radius: 10px;
        box-shadow: 0 10px 25px rgba(0, 0, 0, 0.25);
        border: 1px solid rgba(255, 184, 0, 0.25);
        font-family: system-ui, -apple-system, sans-serif;
        font-size: 13px;
        z-index: 9999;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
      "
    >
      <span style="line-height: 1.3;">
        {lang === 'es' ? 'Utilizamos cookies para analizar el tráfico.' : lang === 'de' ? 'Wir verwenden Cookies zur Analyse des Datenverkehrs.' : 'We use cookies to analyze traffic.'}
      </span>
      <div style="display: flex; gap: 8px; flex-shrink: 0;">
        <button
          id="btn-decline"
          type="button"
          style="
            background: transparent;
            color: #FFF7EA;
            border: 1px solid rgba(255, 247, 234, 0.4);
            padding: 5px 10px;
            border-radius: 6px;
            cursor: pointer;
            font-size: 12px;
          "
        >
          {lang === 'es' ? 'Rechazar' : lang === 'de' ? 'Ablehnen' : 'Decline'}
        </button>
        <button
          id="btn-accept"
          type="button"
          style="
            background: #FFB800;
            color: #292521;
            border: none;
            font-weight: bold;
            padding: 5px 12px;
            border-radius: 6px;
            cursor: pointer;
            font-size: 12px;
          "
        >
          {lang === 'es' ? 'Aceptar' : lang === 'de' ? 'Akzeptieren' : 'Accept'}
        </button>
      </div>
    </div>

    <script is:inline>
      (function () {
        const banner = document.getElementById('cookie-banner');
        const acceptBtn = document.getElementById('btn-accept');
        const declineBtn = document.getElementById('btn-decline');

        if (!banner || !acceptBtn || !declineBtn) return;

        // Check if user has already made a choice
        const userConsent = localStorage.getItem('cookie_consent');

        if (!userConsent) {
          // Show banner if no prior choice exists
          banner.style.display = 'flex';
        } else if (userConsent === 'granted') {
          // Restore 'granted' consent state if previously accepted
          gtag('consent', 'update', {
            'analytics_storage': 'granted'
          });
        }

        // Accept action
        acceptBtn.addEventListener('click', function () {
          localStorage.setItem('cookie_consent', 'granted');
          gtag('consent', 'update', {
            'analytics_storage': 'granted'
          });
          banner.style.display = 'none';
        });

        // Decline action
        declineBtn.addEventListener('click', function () {
          localStorage.setItem('cookie_consent', 'denied');
          gtag('consent', 'update', {
            'analytics_storage': 'denied'
          });
          banner.style.display = 'none';
        });
      })();
    </script>
  </body>
</html>

files.src/pages/[lang]/personas.astro:
---
import Layout from '@/layouts/Layout.astro';
import { Badge } from '@/components/ui/badge';
import { Card } from '@/components/ui/card';
import PersonCard from '@/components/personas/PersonCard';
import { Users, Quote, Sparkles } from 'lucide-react';
import { getCollection } from 'astro:content';
import { personasData } from '@/data/personasData';
import { getTranslations, supportedLanguages } from '@/lib/i18n';
import { generatePersonSchema, generateBreadcrumbSchema } from '@/lib/seo';

export function getStaticPaths() {
  return supportedLanguages.map((lang) => ({
    params: { lang },
  }));
}

const { lang = 'es' } = Astro.params;
const currentLang = (lang === 'es' || lang === 'en' || lang === 'de') ? lang : 'es';

// Get JSON content from content collection
const pagesCollection = await getCollection('pages');
const personasEntry = pagesCollection.find((p) => p.id === 'personas' || p.id.includes('personas'));
const jsonContent = personasEntry ? personasEntry.data : null;

// Fallback to personasData
const fallbackContent = personasData[currentLang] || personasData.es;

const badge = jsonContent?.badge?.[currentLang] || fallbackContent.badge;
const titleText = jsonContent?.title?.[currentLang] || fallbackContent.title;
const subtitle = jsonContent?.subtitle?.[currentLang] || fallbackContent.subtitle;
const chefNote = jsonContent?.chefNote?.[currentLang] || fallbackContent.chefNote;

const content = {
  badge,
  title: titleText,
  subtitle,
  chefNote,
  categories: fallbackContent.categories,
};
const t = getTranslations(lang);

function formatSafetyText(text: string) {
  if (!text) return '';
  return text
    .replace(/(\*\*.*?\*\*)/g, (match) => {
      return `<strong class="font-bold text-[#8D6E63] bg-[#F5E6BE]/60 px-1 py-0.5 rounded">${match.slice(2, -2)}</strong>`;
    });
}

const title = `${content.title} - tortilladepatatas.org`;
const description = content.subtitle;

const personSchemas = content.categories.flatMap((cat) =>
  cat.personas.map((p) =>
    generatePersonSchema({
      name: p.name,
      jobTitle: p.title,
      description: p.bio,
      image: p.image,
    })
  )
);

const breadcrumbSchema = generateBreadcrumbSchema([
  { name: 'Inicio', url: `/${lang}` },
  { name: content.title, url: `/${lang}/personas` }
]);

const schemas = [...personSchemas, breadcrumbSchema];
---

<Layout title={title} description={description} lang={lang} schema={schemas}>
  <div class="container mx-auto px-4 py-10 md:py-16 max-w-6xl space-y-12">
    <!-- Header -->
    <div class="text-center max-w-3xl mx-auto space-y-3">
      <Badge variant="secondary" class="mb-2 px-3.5 py-1 text-xs font-bold bg-[#F5E6BE] text-[#8D6E63] border border-[#E8E2D5] inline-flex items-center gap-1.5 shadow-2xs">
        <Users class="w-3.5 h-3.5" />
        {content.badge}
      </Badge>
      <h1 class="text-3xl sm:text-4xl md:text-5xl font-serif-heading font-extrabold tracking-tight text-foreground">
        {content.title}
      </h1>
      <p class="text-base sm:text-lg text-muted-foreground leading-relaxed">
        {content.subtitle}
      </p>
    </div>

    <!-- Chef Note Callout -->
    <Card class="card-notebook p-6 md:p-8 max-w-4xl mx-auto border-l-4 border-l-[#FFB800]">
      <div class="flex items-start gap-4">
        <Quote class="w-8 h-8 text-[#8D6E63] shrink-0 mt-1 opacity-80" />
        <div class="text-sm md:text-base text-foreground leading-relaxed font-medium">
          <p set:html={formatSafetyText(content.chefNote)} />
        </div>
      </div>
    </Card>

    <!-- Categories & Person Cards -->
    <div class="space-y-12">
      {content.categories.map((cat) => (
        <section key={cat.id} class="space-y-6">
          <div class="border-b border-[#E8E2D5] pb-3 flex items-center justify-between">
            <div>
              <h2 class="text-2xl font-serif-heading font-bold text-foreground flex items-center gap-2">
                <Sparkles class="w-5 h-5 text-[#FFB800]" />
                {cat.title}
              </h2>
              <p class="text-sm text-muted-foreground mt-0.5">{cat.description}</p>
            </div>
          </div>

          <div class="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
            {cat.personas.map((persona) => (
              <PersonCard persona={persona} lang={lang} />
            ))}
          </div>
        </section>
      ))}
    </div>
  </div>
</Layout>

files.src/pages/[lang]/recipes.astro:
---
import Layout from '@/layouts/Layout.astro';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import LocalizedLink from '@/components/navigation/LocalizedLink';
import { BookOpen, Sparkles, Clock, ExternalLink } from 'lucide-react';
import { getTranslations, supportedLanguages } from '@/lib/i18n';
import { generateRecipeSchema, generateBreadcrumbSchema } from '@/lib/seo';
import { getAllRecipes, resolveRecipeBadges } from '@/lib/taxonomy';

export function getStaticPaths() {
  return supportedLanguages.map((lang) => ({
    params: { lang },
  }));
}

const { lang = 'es' } = Astro.params;
const currentLang = (lang === 'es' || lang === 'en' || lang === 'de') ? lang : 'es';
const t = getTranslations(currentLang);

// Get all recipes from Content Collections
const recipes = await getAllRecipes();

// Resolve badges for each recipe
const recipesWithBadges = await Promise.all(
  recipes.map(async (r) => ({
    ...r,
    badges: await resolveRecipeBadges(r.taxonomyIds, currentLang),
  }))
);

const title = `${t('recipes.title')} - tortilladepatatas.org`;
const description = t('recipes.subtitle');

const recipeSchemas = recipes.map((r) => {
  const rTitle = r.title[currentLang as keyof typeof r.title] || r.title.es;
  const rDesc = r.description[currentLang as keyof typeof r.description] || r.description.es;
  return generateRecipeSchema({
    name: rTitle,
    description: rDesc,
    image: r.image || '/images/clasica.jpg',
    prepTimeMinutes: r.prepTimeMinutes || 15,
    cookTimeMinutes: r.cookTimeMinutes || 20,
    yieldServings: r.yieldServings || 4,
    ingredients: [
      '600g Patatas Agria o Monalisa',
      '6 Huevos camperos frescos (Tamaño L)',
      '150ml Aceite de oliva virgen extra',
      '6g Sal fina'
    ],
    instructions: [
      { step: 'Cortar patatas', text: 'Pelar y cortar las patatas en láminas finas.' },
      { step: 'Confitar patatas', text: 'Confitar en aceite de oliva a fuego medio-bajo (130-140°C).' },
      { step: 'Mezclar con huevo', text: 'Batir los huevos con la sal y agregar las patatas.' },
      { step: 'Cuajar y voltear', text: 'Cuajar a fuego fuerte 1 minuto por cada lado (70°C for 2 minutes).' }
    ]
  });
});

const breadcrumbSchema = generateBreadcrumbSchema([
  { name: 'Inicio', url: `/${currentLang}` },
  { name: t('recipes.title'), url: `/${currentLang}/recipes` }
]);

const schemas = [...recipeSchemas, breadcrumbSchema];
---

<Layout title={title} description={description} lang={currentLang} schema={schemas}>
  <div class="container mx-auto px-4 py-10 md:py-16 max-w-6xl space-y-10">
    <section class="text-center max-w-3xl mx-auto space-y-3">
      <Badge variant="secondary" class="mb-2 px-3.5 py-1 text-xs font-bold bg-[#F5E6BE] text-[#8D6E63] border border-[#E8E2D5] inline-flex items-center gap-1.5 shadow-2xs">
        <BookOpen class="w-3.5 h-3.5" />
        {t("nav.recipes", "Recetas de la Gastronomía")}
      </Badge>
      <h1 class="text-3xl sm:text-4xl md:text-5xl font-serif-heading font-extrabold tracking-tight text-foreground">
        {t('recipes.title')}
      </h1>
      <p class="text-base sm:text-lg text-muted-foreground leading-relaxed">
        {t('recipes.subtitle')}
      </p>
    </section>

    <section class="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
      {recipesWithBadges.map((r, index) => {
        const rTitle = r.title[currentLang as keyof typeof r.title] || r.title.es;
        const rDesc = r.description[currentLang as keyof typeof r.description] || r.description.es;
        const rSlug = r.slug[currentLang as keyof typeof r.slug] || r.slug.es;

        return (
          <article key={r.id} class="card-notebook overflow-hidden rounded-2xl border border-[#E8E2D5] bg-[#FCF9F2] hover:border-[#FFB800] transition-all duration-300 flex flex-col justify-between group">
            <div>
              <div class="h-52 w-full overflow-hidden bg-[#F5E6BE] relative border-b border-[#E8E2D5]">
                <img
                  src={r.image || '/images/clasica.jpg'}
                  alt={rTitle}
                  width="600"
                  height="400"
                  loading={index === 0 ? "eager" : "lazy"}
                  decoding="async"
                  referrerPolicy="no-referrer"
                  class="h-full w-full object-cover group-hover:scale-105 transition-transform duration-300"
                />
                <div class="absolute top-3 right-3 bg-[#FCF9F2]/90 border border-[#E8E2D5] text-[#8D6E63] text-[11px] font-bold px-2.5 py-1 rounded-full shadow-2xs flex items-center gap-1">
                  <Clock class="w-3 h-3 text-[#FFB800]" />
                  <span>{r.time} min</span>
                </div>
              </div>

              <div class="p-5 space-y-3">
                <h2 class="text-xl font-serif-heading font-bold text-[#292521] group-hover:text-[#8D6E63] transition-colors">
                  <a href={`/${currentLang}/recipes/${rSlug}`}>
                    {rTitle}
                  </a>
                </h2>

                <p class="text-xs sm:text-sm text-foreground/80 leading-relaxed line-clamp-3">
                  {rDesc}
                </p>

                <!-- TAXONOMY BADGES -->
                <div class="flex flex-wrap gap-1.5 pt-2">
                  {r.badges.map((b) => (
                    <a
                      href={b.url}
                      class="inline-flex items-center gap-1 text-[11px] font-bold bg-[#F5E6BE]/70 hover:bg-[#F5E6BE] text-[#8D6E63] px-2 py-0.5 rounded-md border border-amber-200 transition-colors"
                    >
                      <span>{b.title}</span>
                    </a>
                  ))}
                </div>
              </div>
            </div>

            <div class="p-5 pt-0 mt-auto">
              <a
                href={`/${currentLang}/recipes/${rSlug}`}
                class="inline-flex items-center gap-1.5 text-xs font-bold text-[#8D6E63] hover:text-[#292521] transition-colors"
              >
                <Sparkles class="w-3.5 h-3.5 text-[#FFB800]" />
                <span>Ver Receta Detallada</span>
                <ExternalLink class="w-3 h-3" />
              </a>
            </div>
          </article>
        );
      })}
    </section>
  </div>
</Layout>

